mapper.update:
UPDATE pf.workspace_environment SET operation_id=#{row.id},pending_operation_id=NULL,fence=#{row.fence},
    state=#{phase},version=version+1,updated_at=clock_timestamp()
WHERE space_id=#{row.spaceId} AND workspace_id=#{row.workspaceId} AND id=#{row.environmentId}
    AND generation=#{row.generation} AND version=#{expectedVersion} AND pending_operation_id=#{row.id}

UPDATE pf.workspace_environment SET state=#{phase},version=version+1,error_code=NULL,updated_at=clock_timestamp(),

    pending_operation_id=#{row.id}
    operation_id=#{row.id},fence=#{row.fence},pending_operation_id=NULL

WHERE id=#{row.environmentId} AND space_id=#{row.spaceId} AND workspace_id=#{row.workspaceId}
    AND version=#{expectedVersion} AND pending_operation_id IS NULL
